type Trust = "verified" | "arguable" | "unverified";

const navigation = [
  ["dashboard", "/", "Dashboard", LayoutDashboard], ["cases", "/cases", "Cases", BriefcaseBusiness],
  ["research", "/research", "Research Hub", Search], ["precedents", "/precedents", "Precedent Intelligence", Network],
  ["strategy", "/strategy", "Strategy Builder", Sparkles], ["drafting", "/drafting", "Drafting Studio", FileText],
  ["linter", "/linter", "Procedural Linter", FileCheck2], ["stress-test", "/stress-test", "Opposition Stress-Test", MessageSquareWarning],
  ["documents", "/documents", "Documents", FolderOpen], ["evaluation", "/evaluation", "Evaluation", Activity],
] as const;

const cases = [
  { name: "Ali vs. Federation", number: "2026-CV-0182", court: "Islamabad High Court", client: "Muhammad Ali", type: "Constitutional", updated: "2 hours ago", status: "Active", trust: "verified" as Trust },
  { name: "Ahmed v. State", number: "2026-CR-0921", court: "Lahore High Court", client: "Fahad Ahmed", type: "Criminal", updated: "Yesterday", status: "Active", trust: "verified" as Trust },
  { name: "ABC Property Dispute", number: "2025-CV-4412", court: "Lahore High Court", client: "ABC Holdings", type: "Property", updated: "2 days ago", status: "Under Review", trust: "arguable" as Trust },
  { name: "Khan Family Succession", number: "2025-CV-3890", court: "Sindh High Court", client: "Sana Khan", type: "Family", updated: "6 days ago", status: "Closed", trust: "unverified" as Trust },
];

const titleMap: Record<PageKey, string> = { dashboard: "Dashboard", cases: "Cases", case: "Ali vs. Federation", research: "Research Hub", precedents: "Precedent Intelligence", strategy: "Strategy Builder", "stress-test": "Opposition Stress-Test", drafting: "Drafting Studio", linter: "Procedural Linter", documents: "Documents", claims: "Opponent Claims", evaluation: "Evaluation Dashboard", settings: "Settings" };

export function TrustBadge({ status = "verified", compact = false }: { status?: Trust; compact?: boolean }) {
  const Icon = status === "verified" ? CheckCircle2 : status === "arguable" ? AlertCircle : X;
  return <span className={cn("inline-flex items-center gap-1 rounded-sm border px-2 py-1 text-[10px] font-bold uppercase", status === "verified" && "border-success/20 bg-success-soft text-success", status === "arguable" && "border-warning/20 bg-warning-soft text-warning", status === "unverified" && "border-danger/20 bg-danger-soft text-danger")}><Icon className="size-3" />{compact ? status : status}</span>;
}

export function FreshnessBadge({ children }: { children: ReactNode }) { return <span className="inline-flex items-center gap-1 text-[11px] font-medium text-muted-foreground"><Clock3 className="size-3" />{children}</span>; }

function Card({ children, className }: { children: ReactNode; className?: string }) { return <div className={cn("rounded-md border bg-card shadow-[0_1px_2px_oklch(0.2_0.02_255/0.04)]", className)}>{children}</div>; }
function SectionHead({ title, action }: { title: string; action?: ReactNode }) { return <div className="mb-4 flex items-center justify-between"><h2 className="text-sm font-bold text-foreground">{title}</h2>{action}</div>; }
function PageIntro({ title, subtitle, actions }: { title: string; subtitle?: string; actions?: ReactNode }) { return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-2xl font-bold tracking-normal text-foreground">{title}</h1>{subtitle && <p className="mt-1 text-sm text-muted-foreground">{subtitle}</p>}</div>{actions && <div className="flex gap-2">{actions}</div>}</div>; }

function Sidebar({ collapsed, onToggle, mobileOpen, onMobileClose }: { collapsed: boolean; onToggle: () => void; mobileOpen: boolean; onMobileClose: () => void }) {
  const path = useRouterState({ select: s => s.location.pathname });
  const side = <div className="flex h-full flex-col bg-navy text-primary-foreground">
    <div className="flex h-16 items-center border-b border-primary-foreground/10 px-4"><div className="flex size-8 shrink-0 items-center justify-center rounded-md bg-primary-foreground text-navy"><Scale className="size-5" /></div>{!collapsed && <div className="ml-3"><div className="text-sm font-bold">CaseGuard AI</div><div className="text-[9px] uppercase text-primary-foreground/55">Trust every claim</div></div>}<Button variant="ghost" size="icon" className="ml-auto hidden text-primary-foreground/70 hover:bg-primary-foreground/10 hover:text-primary-foreground lg:inline-flex" onClick={onToggle}>{collapsed ? <PanelLeftOpen /> : <PanelLeftClose />}</Button></div>
    <nav className="cg-scrollbar flex-1 space-y-1 overflow-y-auto p-2">{navigation.map(([key, href, label, Icon]) => { const active = path === href || (key === "cases" && path === "/case"); return <Link key={key} to={href} onClick={onMobileClose} title={collapsed ? label : undefined} className={cn("flex h-10 items-center gap-3 rounded-sm px-3 text-[13px] font-medium text-primary-foreground/65 transition-colors hover:bg-primary-foreground/8 hover:text-primary-foreground", active && "bg-primary-foreground/12 text-primary-foreground before:-ml-3 before:h-5 before:w-[3px] before:bg-primary-foreground")}><Icon className="size-[17px] shrink-0" />{!collapsed && <span>{label}</span>}</Link>; })}</nav>
    <div className="border-t border-primary-foreground/10 p-2"><Link to="/settings" className="flex h-10 items-center gap-3 rounded-sm px-3 text-[13px] text-primary-foreground/65 hover:bg-primary-foreground/8"><Settings className="size-[17px]" />{!collapsed && "Settings"}</Link><div className="flex h-12 items-center gap-3 px-3"><div className="flex size-8 items-center justify-center rounded-full bg-primary-foreground/15 text-xs font-bold">AK</div>{!collapsed && <div className="min-w-0"><p className="truncate text-xs font-semibold">Ayesha Khan</p><p className="truncate text-[10px] text-primary-foreground/45">Advocate</p></div>}</div></div>
  </div>;
  return <><aside className={cn("fixed inset-y-0 left-0 z-40 hidden transition-all lg:block", collapsed ? "w-16" : "w-64")}>{side}</aside>{mobileOpen && <div className="fixed inset-0 z-50 lg:hidden"><button aria-label="Close menu" className="absolute inset-0 bg-navy/55" onClick={onMobileClose} /><aside className="relative h-full w-72">{side}</aside></div>}</>;
}

function Header({ title, onMenu, onNotifications }: { title: string; onMenu: () => void; onNotifications: () => void }) {
  return <header className="sticky top-0 z-30 flex h-16 items-center gap-4 border-b bg-card/95 px-4 backdrop-blur sm:px-6"><Button variant="ghost" size="icon" className="lg:hidden" onClick={onMenu}><Menu /></Button><div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex"><span>CaseGuard</span><ChevronRight className="size-3" /><span className="font-medium text-foreground">{title}</span></div><div className="ml-auto hidden w-full max-w-sm md:block"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="h-9 bg-muted/60 pl-9" placeholder="Search cases, sources, documents..."/></div></div><Button variant="ghost" size="icon" className="relative" onClick={onNotifications}><Bell/><span className="absolute right-2 top-2 size-2 rounded-full bg-danger ring-2 ring-card"/></Button><DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" className="h-10 px-2"><span className="flex size-7 items-center justify-center rounded-full bg-navy text-[10px] font-bold text-primary-foreground">AK</span><span className="hidden text-xs sm:inline">Ayesha Khan</span><ChevronDown className="size-3"/></Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="w-52"><DropdownMenuLabel><div>Ayesha Khan</div><div className="text-xs font-normal text-muted-foreground">ayesha@chambers.pk</div></DropdownMenuLabel><DropdownMenuSeparator/><DropdownMenuItem><CircleUserRound/>Profile</DropdownMenuItem><DropdownMenuItem><Settings/>Settings</DropdownMenuItem><DropdownMenuItem><HelpCircle/>Help centre</DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem>Sign out</DropdownMenuItem></DropdownMenuContent></DropdownMenu></header>;
}

function StatCard({ label, value, note, icon: Icon, tone = "info" }: { label: string; value: string; note: string; icon: typeof Activity; tone?: "info" | "success" | "warning" }) { return <Card className="p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-bold">{value}</p></div><span className={cn("flex size-9 items-center justify-center rounded-md", tone === "success" ? "bg-success-soft text-success" : tone === "warning" ? "bg-warning-soft text-warning" : "bg-info-soft text-info")}><Icon className="size-4"/></span></div><p className="mt-3 text-[11px] text-muted-foreground">{note}</p></Card>; }

function CasesTable({ compact = false }: { compact?: boolean }) { const nav = useNavigate(); return <div className="overflow-hidden rounded-md border bg-card"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-xs"><thead className="bg-muted/70 text-[10px] uppercase text-muted-foreground"><tr>{["Case","Case number","Court", compact ? "Type" : "Client", "Last activity","Status","Trust"].map(x=><th className="px-4 py-3 font-semibold" key={x}>{x}</th>)}</tr></thead><tbody>{cases.slice(0, compact ? 3 : 4).map(c=><tr key={c.number} onClick={()=>nav({to:"/case"})} className="cursor-pointer border-t transition-colors hover:bg-muted/50"><td className="px-4 py-4 font-semibold text-primary">{c.name}</td><td className="px-4 font-mono text-[11px]">{c.number}</td><td className="px-4">{c.court}</td><td className="px-4">{compact ? c.type : c.client}</td><td className="px-4 text-muted-foreground">{c.updated}</td><td className="px-4"><span className="rounded-sm bg-secondary px-2 py-1 font-medium text-secondary-foreground">{c.status}</span></td><td className="px-4"><TrustBadge status={c.trust}/></td></tr>)}</tbody></table></div></div>; }

function Dashboard() { const data=[{name:"Verified",value:1284,fill:"var(--success)"},{name:"Arguable",value:96,fill:"var(--warning)"},{name:"Unverified",value:18,fill:"var(--danger)"}]; return <><PageIntro title="Good morning, Ayesha" subtitle="Here’s what needs your attention today."/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Active Cases" value="24" note="↑ 3 opened this month" icon={BriefcaseBusiness}/><StatCard label="Pending Reviews" value="7" note="2 due before Friday" icon={FileSearch} tone="warning"/><StatCard label="Verified Sources" value="1,284" note="↑ 42 verified this week" icon={ShieldCheck} tone="success"/><StatCard label="Sources Requiring Review" value="18" note="4 affect active matters" icon={AlertCircle} tone="warning"/></div><div className="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1.7fr)_minmax(300px,.7fr)]"><section><SectionHead title="Active Cases" action={<Link to="/cases" className="text-xs font-semibold text-primary">View all</Link>}/><CasesTable compact/></section><Card className="p-5"><SectionHead title="Trust Overview"/><div className="mx-auto h-44 max-w-[220px]"><ResponsiveContainer><PieChart><Pie data={data} innerRadius={52} outerRadius={70} dataKey="value" strokeWidth={0}>{data.map(d=><Cell key={d.name} fill={d.fill}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer></div><div className="grid grid-cols-3 gap-2 text-center">{data.map(d=><div key={d.name}><div className="text-base font-bold">{d.value}</div><div className="text-[10px] text-muted-foreground">{d.name}</div></div>)}</div><div className="mt-4 rounded-sm bg-warning-soft p-3 text-xs text-warning"><strong>18 sources</strong> have not been recently reverified.</div><Button variant="outline" className="mt-3 w-full">Review Sources</Button></Card></div><div className="mt-6"><SectionHead title="Recent Activity"/><Card className="divide-y">{[{Icon:CheckCircle2,title:"Citation verified",detail:"Ali vs. Federation · PLD 2022 SC 123",time:"12 minutes ago"},{Icon:Upload,title:"Document uploaded",detail:"Ahmed v. State · Police report",time:"1 hour ago"},{Icon:Sparkles,title:"Strategy generated",detail:"ABC Property Dispute",time:"3 hours ago"},{Icon:Network,title:"Precedent relationship reviewed",detail:"Ali vs. Federation",time:"Yesterday"},{Icon:FileCheck2,title:"Draft procedural check completed",detail:"Khan Family Succession",time:"Yesterday"}].map(({Icon,title,detail,time})=><div className="flex gap-3 p-4" key={title}><span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-info-soft text-info"><Icon className="size-4"/></span><div className="min-w-0 flex-1"><p className="text-xs font-semibold">{title}</p><p className="text-xs text-muted-foreground">{detail}</p></div><time className="text-[11px] text-muted-foreground">{time}</time></div>)}</Card></div></>; }

function CasesPage() { const [filter,setFilter]=useState("All"); const [search,setSearch]=useState(""); const shown=cases.filter(c=>(filter==="All"||c.status===filter)&&c.name.toLowerCase().includes(search.toLowerCase())); return <><PageIntro title="Cases" subtitle="Manage matters, evidence, and legal work in one place." actions={<Button><Plus/>New Case</Button>}/><Card className="mb-4 p-4"><div className="flex flex-col gap-3 md:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input value={search} onChange={e=>setSearch(e.target.value)} className="pl-9" placeholder="Search cases"/></div><div className="flex gap-1">{["All","Active","Under Review","Closed"].map(x=><Button key={x} size="sm" variant={filter===x?"default":"ghost"} onClick={()=>setFilter(x)}>{x}</Button>)}</div></div></Card><div className="grid gap-3 md:hidden">{shown.map(c=><Link to="/case" key={c.number}><Card className="p-4"><div className="flex justify-between gap-3"><div><h3 className="font-semibold">{c.name}</h3><p className="mt-1 font-mono text-xs text-muted-foreground">{c.number}</p></div><TrustBadge status={c.trust}/></div><div className="mt-4 grid grid-cols-2 gap-2 text-xs"><span>{c.court}</span><span>{c.client}</span></div></Card></Link>)}</div><div className="hidden md:block"><CasesTable/></div></>; }

const claims=[{title:"The administrative order was issued within delegated authority.",evidence:"Notification No. SRO-211/2025",basis:"Section 14, Administrative Powers Act",analysis:"Delegation exists, but the record does not show application of mind.",trust:"arguable" as Trust},{title:"The petitioner received adequate opportunity of hearing.",evidence:"Notice dated 04 January 2026",basis:"Article 10A, Constitution of Pakistan",analysis:"The notice allowed 24 hours and omitted the adverse material relied upon.",trust:"unverified" as Trust},{title:"Alternative statutory remedy bars constitutional jurisdiction.",evidence:"Departmental appeal procedure",basis:"Article 199, Constitution of Pakistan",analysis:"Exceptions may apply where natural justice is demonstrably breached.",trust:"verified" as Trust}];
function CasePage(){const [tab,setTab]=useState("Overview");return <><PageIntro title="Ali vs. Federation" subtitle="2026-CV-0182 · Islamabad High Court · Active" actions={<><Button asChild variant="outline"><Link to="/documents"><FolderOpen/>Open Documents</Link></Button><Button asChild><Link to="/strategy"><Sparkles/>Generate Strategy</Link></Button></>}/><div className="mb-6 flex gap-1 overflow-x-auto border-b">{["Overview","Facts","Documents","Timeline","Research","Strategy","Drafts","Opponent Claims"].map(x=><button key={x} onClick={()=>setTab(x)} className={cn("whitespace-nowrap border-b-2 px-3 py-3 text-xs font-semibold",tab===x?"border-primary text-primary":"border-transparent text-muted-foreground")}>{x}</button>)}</div>{tab!=="Overview"?<Card className="p-8"><h2 className="text-lg font-bold">{tab}</h2><p className="mt-2 text-sm text-muted-foreground">This case workspace keeps {tab.toLowerCase()} connected to verified sources and the complete matter record.</p>{tab==="Opponent Claims"&&<div className="mt-5 grid gap-3">{claims.map(c=><ClaimCard key={c.title} {...c}/>)}</div>}</Card>:<div className="grid gap-6 xl:grid-cols-[1.4fr_.8fr]"><div className="space-y-6"><Card className="p-5"><SectionHead title="Case Summary"/><p className="text-sm leading-6 text-muted-foreground">Muhammad Ali challenges an administrative order terminating his statutory licence without disclosure of the adverse material or a meaningful opportunity of hearing. The petition invokes Article 199 and alleges violations of due process, natural justice, and lawful exercise of delegated authority.</p><div className="mt-4 flex items-center gap-3 border-t pt-4"><TrustBadge status="verified"/><FreshnessBadge>Verified 2 days ago</FreshnessBadge></div></Card><div><SectionHead title="Key Facts"/><div className="grid gap-3 sm:grid-cols-2">{[["04 Jan 2026","Show-cause notice served with 24-hour response period."],["06 Jan 2026","Licence suspended before the written response was considered."],["12 Jan 2026","Departmental appeal filed; no hearing date issued."],["03 Feb 2026","Constitutional petition lodged before IHC."]].map(([d,t])=><Card className="p-4" key={d}><p className="text-[10px] font-bold uppercase text-primary">{d}</p><p className="mt-2 text-xs leading-5">{t}</p></Card>)}</div></div><div><SectionHead title="Opponent Claims" action={<Link to="/claims" className="text-xs font-semibold text-primary">Analyze all</Link>}/><div className="space-y-3">{claims.map(c=><ClaimCard key={c.title} {...c}/>)}</div></div></div><div className="space-y-6"><Card className="p-5"><SectionHead title="Parties"/><div className="space-y-4 text-xs"><div><p className="text-muted-foreground">Petitioner</p><p className="mt-1 font-semibold">Muhammad Ali</p></div><div><p className="text-muted-foreground">Respondent</p><p className="mt-1 font-semibold">Federation of Pakistan</p></div></div></Card><Card className="p-5"><SectionHead title="Current Work"/><p className="text-sm leading-6">Preparing arguments regarding validity of the challenged administrative decision.</p><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full w-[68%] bg-primary"/></div><p className="mt-2 text-[11px] text-muted-foreground">Strategy readiness 68%</p></Card><Card className="p-5"><SectionHead title="Key Legal Issues"/><ul className="space-y-3 text-xs">{["Denial of a meaningful opportunity of hearing","Authority acting beyond statutory powers","Maintainability despite alternative remedy"].map((x,i)=><li className="flex gap-2" key={x}><span className="font-bold text-primary">0{i+1}</span><span>{x}</span></li>)}</ul></Card></div></div>}</>;}
function ClaimCard(c:{title:string;evidence:string;basis:string;analysis:string;trust:Trust}){return <Card className="p-4"><div className="flex items-start justify-between gap-3"><h3 className="text-sm font-semibold leading-5">{c.title}</h3><TrustBadge status={c.trust}/></div><div className="mt-3 grid gap-3 text-xs sm:grid-cols-2"><div><span className="text-muted-foreground">Evidence</span><p className="mt-1">{c.evidence}</p></div><div><span className="text-muted-foreground">Legal basis</span><p className="mt-1">{c.basis}</p></div></div><p className="mt-3 border-l-2 border-primary pl-3 text-xs leading-5 text-muted-foreground"><strong className="text-foreground">CaseGuard analysis:</strong> {c.analysis}</p></Card>}

function Research(){const [source,setSource]=useState(false);const [query,setQuery]=useState("Can an administrative order be challenged when the affected party was not given an opportunity of hearing?");return <><PageIntro title="Research Hub" subtitle="Research Pakistani law with evidence you can inspect."/><Card className="p-4"><div className="relative"><Search className="absolute left-4 top-4 size-5 text-muted-foreground"/><textarea value={query} onChange={e=>setQuery(e.target.value)} className="min-h-24 w-full resize-none rounded-md border bg-background py-3 pl-12 pr-28 text-sm outline-none focus:ring-2 focus:ring-ring"/><Button className="absolute bottom-3 right-3">Research</Button></div><div className="mt-3 flex flex-wrap gap-2">{["All","Statutes","Judgments","Precedents","Case Documents","Court","Jurisdiction","Date","Legal Area"].map((x,i)=><Button key={x} size="sm" variant={i===0?"default":"outline"}>{x}{i>4&&<ChevronDown/>}</Button>)}</div></Card><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><Card className="p-6"><div className="mb-5 flex items-center justify-between"><span className="flex items-center gap-2 text-xs font-bold text-primary"><Bot className="size-4"/>CASEGUARD ANALYSIS</span><span className="text-[11px] text-muted-foreground">Generated from 7 sources</span></div><h2 className="text-lg font-bold">Right to a fair hearing in administrative action</h2><div className="mt-4 space-y-4 text-sm leading-7 text-muted-foreground"><p>Yes. An administrative order may be challenged where the affected party was denied a meaningful opportunity of hearing. Pakistani courts treat fair hearing as a component of due process under Article 10A of the Constitution <Citation n={1} trust="verified" onClick={()=>setSource(true)}/>.</p><p>The Supreme Court has held that a notice must disclose the substance of the case and allow a reasonable opportunity to respond <Citation n={2} trust="verified" onClick={()=>setSource(true)}/>. A merely formal notice may not cure the defect where adverse material remains undisclosed <Citation n={3} trust="arguable" onClick={()=>setSource(true)}/>.</p><div className="rounded-sm border-l-4 border-warning bg-warning-soft p-4 text-warning"><strong>Application is arguable.</strong> The strength of the challenge will depend on statutory language, urgency, and whether an effective alternative remedy exists.</div></div><div className="mt-6 border-t pt-4"><div className="flex flex-wrap items-center gap-3"><TrustBadge status="verified"/><span className="text-xs font-semibold">High confidence</span><FreshnessBadge>Verified 12 Sep 2026</FreshnessBadge></div></div></Card><Card className="p-5"><SectionHead title="Evidence & Sources"/><div className="space-y-3">{[["1","Article 10A — Constitution of Pakistan","Constitutional text","verified"],["2","Example Case v. Federation","PLD 2022 SC 123","verified"],["3","Ahmed v. Licensing Authority","2021 CLC 884","arguable"]].map(([n,t,s,trust])=><button onClick={()=>setSource(true)} key={n} className="w-full rounded-sm border p-3 text-left transition-colors hover:border-primary hover:bg-info-soft"><div className="flex gap-3"><span className="flex size-6 shrink-0 items-center justify-center rounded-sm bg-navy text-xs font-bold text-primary-foreground">{n}</span><div><p className="text-xs font-semibold">{t}</p><p className="mt-1 text-[11px] text-muted-foreground">{s}</p><div className="mt-2"><TrustBadge status={trust as Trust}/></div></div></div></button>)}</div></Card></div><SourceDrawer open={source} onOpenChange={setSource}/></>}
function Citation({n,trust,onClick}:{n:number;trust:Trust;onClick:()=>void}){return <button onClick={onClick} className={cn("mx-0.5 inline-flex size-5 items-center justify-center rounded-sm align-middle text-[10px] font-bold",trust==="verified"?"bg-success-soft text-success":"bg-warning-soft text-warning")}>[{n}]</button>}
function SourceDrawer({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){return <Sheet open={open} onOpenChange={onOpenChange}><SheetContent className="w-full overflow-y-auto sm:max-w-lg"><SheetHeader><SheetTitle>Evidence detail</SheetTitle><SheetDescription>Verified source record and supporting passage.</SheetDescription></SheetHeader><div className="mt-6"><div className="flex items-center justify-between"><TrustBadge status="verified"/><FreshnessBadge>Verified 12 Sep 2026</FreshnessBadge></div><dl className="mt-6 grid grid-cols-2 gap-5 text-xs">{[["Source","Supreme Court of Pakistan"],["Case","Example Case v. Federation"],["Citation","PLD 2022 SC 123"],["Court","Supreme Court of Pakistan"],["Date","15 March 2022"],["Confidence","High"]].map(([k,v])=><div key={k}><dt className="text-muted-foreground">{k}</dt><dd className="mt-1 font-semibold">{v}</dd></div>)}</dl><div className="mt-6 border-t pt-6"><h3 className="text-sm font-bold">Why this source supports the claim</h3><blockquote className="mt-3 border-l-2 border-primary bg-muted/60 p-4 text-sm leading-6">“A person whose rights are adversely affected must be afforded a fair and meaningful opportunity to meet the case against them.”</blockquote></div><div className="mt-6 flex flex-wrap gap-2"><Button>Open Source</Button><Button variant="outline">View Case</Button><Button variant="outline">View Precedent Graph</Button></div><p className="mt-8 text-[11px] text-muted-foreground">Prototype content for demonstration only. Not legal advice.</p></div></SheetContent></Sheet>}

const nodes=[{x:52,y:45,name:"Ali v. Federation",cite:"2026 IHC 182",court:"IHC",status:"Current"},{x:25,y:25,name:"Federation v. Ahmed",cite:"PLD 2022 SC 123",court:"Supreme Court",status:"Binding"},{x:78,y:25,name:"Khan v. Authority",cite:"2020 SCMR 892",court:"Supreme Court",status:"Distinguished"},{x:18,y:72,name:"Raza v. Province",cite:"2019 CLC 441",court:"LHC",status:"Persuasive"},{x:72,y:72,name:"Nadeem v. State",cite:"PLD 2018 SC 95",court:"Supreme Court",status:"Current"}];
function Precedents(){const [selected,setSelected]=useState(nodes[0] ?? {x:52,y:45,name:"Ali v. Federation",cite:"2026 IHC 182",court:"IHC",status:"Current"});const [year,setYear]=useState(2026);return <><PageIntro title="Precedent Intelligence" subtitle="Trace how authority has evolved, not just where it was cited."/><Card className="mb-4 p-4"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"/><Input className="pl-9" placeholder="Search cases or precedents..."/></div></Card><div className="grid gap-5 xl:grid-cols-[1fr_320px]"><Card className="overflow-hidden"><div className="border-b px-5 py-4"><div className="flex items-center justify-between"><h2 className="text-sm font-bold">Relationship graph</h2><span className="text-[11px] text-muted-foreground">12 cases · 18 relationships</span></div></div><div className="relative h-[470px] overflow-hidden bg-[linear-gradient(var(--border)_1px,transparent_1px),linear-gradient(90deg,var(--border)_1px,transparent_1px)] bg-[size:32px_32px]"><svg className="absolute inset-0 h-full w-full" aria-hidden="true"><line x1="52%" y1="45%" x2="25%" y2="25%" stroke="var(--success)" strokeWidth="2"/><line x1="52%" y1="45%" x2="78%" y2="25%" stroke="var(--warning)" strokeWidth="2" strokeDasharray="5 4"/><line x1="52%" y1="45%" x2="18%" y2="72%" stroke="var(--info)" strokeWidth="2"/><line x1="52%" y1="45%" x2="72%" y2="72%" stroke="var(--danger)" strokeWidth="2"/></svg>{nodes.map((n,i)=><button key={n.name} onClick={()=>setSelected(n)} style={{left:`${n.x}%`,top:`${n.y}%`}} className={cn("absolute w-36 -translate-x-1/2 -translate-y-1/2 rounded-md border bg-card p-3 text-left shadow-md transition hover:border-primary hover:shadow-lg",selected.name===n.name&&"border-primary ring-2 ring-primary/15")}><span className="text-[10px] font-bold text-primary">{n.court}</span><p className="mt-1 truncate text-xs font-semibold">{n.name}</p><p className="mt-1 text-[9px] text-muted-foreground">{n.cite}</p>{i===1&&<span className="mt-2 inline-flex items-center gap-1 text-[9px] font-bold text-success"><Check className="size-3"/>Human confirmed</span>}</button>)}</div><div className="border-t p-5"><div className="flex items-center justify-between text-[10px] font-bold text-muted-foreground"><span>LAW AT THE TIME</span><span>{year}</span><span>LAW TODAY</span></div><input aria-label="Legal timeline year" type="range" min="2016" max="2026" value={year} onChange={e=>setYear(Number(e.target.value))} className="mt-2 w-full accent-primary"/><div className="mt-4 flex flex-wrap gap-4 text-[10px]">{[["bg-success","Cites"],["bg-danger","Overrules"],["bg-warning","Distinguishes"],["bg-info","Amends"]].map(([c,l])=><span className="flex items-center gap-2" key={l}><i className={cn("size-2 rounded-full",c)}/>{l}</span>)}</div></div></Card><Card className="p-5"><span className="text-[10px] font-bold text-primary">SELECTED PRECEDENT</span><h2 className="mt-2 text-base font-bold">{selected.name}</h2><p className="mt-1 font-mono text-xs text-muted-foreground">{selected.cite}</p><div className="mt-5 space-y-3 border-y py-5 text-xs">{[["Court",selected.court],["Date","15 March 2022"],["Current status",selected.status],["Last verified","12 September 2026"]].map(([a,b])=><div className="flex justify-between gap-3" key={a}><span className="text-muted-foreground">{a}</span><strong>{b}</strong></div>)}</div><h3 className="mt-5 text-xs font-bold">Relationships</h3><div className="mt-3 grid grid-cols-2 gap-2">{[["Cites","6"],["Cited By","14"],["Overruled","0"],["Distinguishes","3"],["Related","9"]].map(([a,b])=><div className="rounded-sm bg-muted p-3" key={a}><div className="text-lg font-bold">{b}</div><div className="text-[10px] text-muted-foreground">{a}</div></div>)}</div><div className="mt-4"><TrustBadge status="verified"/></div></Card></div></>}

function Strategy(){const [step,setStep]=useState(3);const steps=["Case Facts","Legal Issues","Arguments","Review"];return <><PageIntro title="Strategy Builder" subtitle="Build an evidence-backed litigation strategy."/><div className="mb-6 grid grid-cols-4 overflow-hidden rounded-md border bg-card">{steps.map((s,i)=><button key={s} onClick={()=>setStep(i)} className={cn("border-r px-3 py-4 text-xs font-semibold last:border-r-0",i===step?"bg-navy text-primary-foreground":i<step?"bg-success-soft text-success":"text-muted-foreground")}><span className="mr-2 hidden sm:inline">{i<step?<Check className="inline size-3"/>:`0${i+1}`}</span>{s}</button>)}</div>{step<2?<Card className="p-6"><h2 className="text-lg font-bold">{steps[step]}</h2><p className="mt-2 text-sm text-muted-foreground">{step===0?"Review and edit structured facts extracted from the selected case record.":"Confirm the legal issues CaseGuard should address."}</p><div className="mt-5 space-y-3">{(step===0?["Notice allowed only 24 hours to respond.","Adverse material was not disclosed.","Decision issued before departmental appeal was heard."]:["Whether the administrative order violates principles of natural justice.","Whether the authority acted beyond its statutory powers."]).map(x=><label className="flex items-start gap-3 rounded-sm border p-4 text-sm" key={x}><input type="checkbox" defaultChecked className="mt-1 accent-primary"/><span>{x}</span></label>)}</div><Button className="mt-5" onClick={()=>setStep(step+1)}>Continue<ChevronRight/></Button></Card>:<div className="space-y-4">{[{title:"Denial of procedural fairness",strength:"STRONG",trust:"verified" as Trust,desc:"The 24-hour notice and non-disclosure of adverse material support a direct Article 10A challenge.",weak:"Respondent may rely on statutory urgency powers."},{title:"Ultra vires exercise of delegated power",strength:"MODERATE",trust:"arguable" as Trust,desc:"The impugned order appears to exceed the purpose and limits of the enabling provision.",weak:"Broad discretionary wording may favour the authority."},{title:"Exception to alternative remedy rule",strength:"MODERATE",trust:"verified" as Trust,desc:"Constitutional jurisdiction can remain available where natural justice is facially breached.",weak:"Court may still require exhaustion of appeal."}].map(a=><Card className="p-5" key={a.title}><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2"><span className={cn("text-[10px] font-bold",a.strength==="STRONG"?"text-success":"text-warning")}>{a.strength}</span><TrustBadge status={a.trust}/></div><h2 className="mt-2 text-base font-bold">{a.title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{a.desc}</p></div><Button variant="outline" size="sm">View Sources</Button></div><div className="mt-4 grid gap-3 border-t pt-4 md:grid-cols-3"><div><p className="text-[10px] font-bold text-muted-foreground">SUPPORTING STATUTE</p><p className="mt-1 text-xs">Article 10A, Constitution</p></div><div><p className="text-[10px] font-bold text-muted-foreground">PRECEDENT</p><p className="mt-1 text-xs">PLD 2022 SC 123</p></div><div><p className="text-[10px] font-bold text-danger">POTENTIAL WEAKNESS</p><p className="mt-1 text-xs">{a.weak}</p></div></div><details className="mt-4 text-xs"><summary className="cursor-pointer font-semibold text-primary">Why CaseGuard suggested this</summary><p className="mt-2 rounded-sm bg-info-soft p-3 text-muted-foreground">The argument links verified case facts with controlling constitutional text and currently valid precedent.</p></details></Card>)}</div>}</>}

function StressTest(){const [loading,setLoading]=useState(false);const [shown,setShown]=useState(true);const run=()=>{setLoading(true);setShown(false);setTimeout(()=>{setLoading(false);setShown(true)},1100)};return <><PageIntro title="Opposition Stress-Test" subtitle="Challenge your strategy before the opposing counsel does." actions={<Button disabled={loading} onClick={run}>{loading?<LoaderCircle className="animate-spin"/>:<MessageSquareWarning/>}Run Stress-Test</Button>}/><Card className="mb-6 p-5"><span className="text-[10px] font-bold text-primary">CURRENT STRATEGY</span><h2 className="mt-2 font-bold">Administrative action — natural justice challenge</h2><p className="mt-2 text-sm text-muted-foreground">3 primary arguments · 7 authorities · 12 evidence items</p></Card>{loading&&<Card className="flex h-64 flex-col items-center justify-center"><LoaderCircle className="size-7 animate-spin text-primary"/><p className="mt-3 text-sm font-semibold">Testing arguments against opposing authority…</p></Card>}{shown&&<><SectionHead title="Opposing Arguments"/><div className="grid gap-4 lg:grid-cols-3">{[{t:"Alternative remedy is adequate",s:"High",a:"2023 SCMR 411",d:"Courts ordinarily decline Article 199 relief where a statutory appeal remains available."},{t:"Urgency justified abbreviated notice",s:"Medium",a:"PLD 2020 SC 88",d:"The statutory scheme permits immediate action to protect the public interest."},{t:"No material prejudice shown",s:"Low",a:"2021 CLC 884",d:"Respondent may argue the same outcome followed even after a full hearing."}].map(x=><Card className="p-5" key={x.t}><span className={cn("text-[10px] font-bold uppercase",x.s==="High"?"text-danger":x.s==="Medium"?"text-warning":"text-success")}>{x.s} severity</span><h3 className="mt-2 font-bold">{x.t}</h3><p className="mt-3 text-xs leading-5 text-muted-foreground">{x.d}</p><div className="mt-4 border-t pt-3 text-xs"><span className="text-muted-foreground">Supporting authority</span><p className="mt-1 font-semibold">{x.a}</p></div><div className="mt-3 rounded-sm bg-info-soft p-3 text-xs"><strong>Recommended response:</strong> Distinguish on the facts and demonstrate actual procedural prejudice.</div></Card>)}</div><Card className="mt-6 p-5"><SectionHead title="Strategy Weakness Summary"/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5">{[["Strong Points","Constitutional basis; undisputed timeline"],["Vulnerabilities","Alternative remedy objection"],["Missing Evidence","Dispatch record; internal minutes"],["Potential Counterarguments","Urgency and no prejudice"],["Recommended Improvements","Add prejudice chronology"]].map(([a,b])=><div key={a}><p className="text-[10px] font-bold uppercase text-muted-foreground">{a}</p><p className="mt-2 text-xs leading-5">{b}</p></div>)}</div></Card></>}</>}

function Drafting(){const [template,setTemplate]=useState("Petition");const [saved,setSaved]=useState(false);return <div className="-m-4 sm:-m-6 lg:-m-8"><div className="flex min-h-[calc(100vh-64px)] flex-col"><div className="flex flex-wrap items-center gap-2 border-b bg-card px-5 py-3"><div className="mr-auto"><h1 className="text-lg font-bold">Drafting Studio</h1><p className="text-[11px] text-muted-foreground">Constitutional Petition — Ali vs. Federation</p></div><Button variant="outline" size="sm" onClick={()=>{setSaved(true);setTimeout(()=>setSaved(false),1500)}}>{saved?<Check/>:<FileText/>}{saved?"Saved":"Save"}</Button><Button variant="outline" size="sm"><FileSearch/>Preview</Button><Button variant="outline" size="sm"><History/>Version History</Button><Button size="sm" asChild><Link to="/linter"><FileCheck2/>Run Procedural Check</Link></Button><Button variant="outline" size="sm"><Upload/>Export</Button></div><div className="grid flex-1 xl:grid-cols-[220px_1fr_280px]"><aside className="border-r bg-card p-4"><p className="mb-3 text-[10px] font-bold uppercase text-muted-foreground">Templates</p>{["Petition","Pleading","Written Statement","Application","Other"].map(x=><button key={x} onClick={()=>setTemplate(x)} className={cn("mb-1 flex w-full items-center gap-2 rounded-sm px-3 py-2 text-left text-xs",template===x?"bg-secondary font-semibold text-primary":"hover:bg-muted")}><FileText className="size-4"/>{x}</button>)}</aside><main className="bg-muted/60 p-4 sm:p-8"><article contentEditable suppressContentEditableWarning className="mx-auto min-h-[850px] max-w-[760px] bg-card px-8 py-12 text-[13px] leading-7 shadow-sm outline-none sm:px-16"><header className="text-center"><h2 className="text-base font-bold">IN THE ISLAMABAD HIGH COURT</h2><p className="mt-2 font-semibold">Constitutional Petition No. 2026 of 2026</p></header><div className="my-8 grid grid-cols-[1fr_auto] gap-8"><p><strong>Muhammad Ali</strong><br/>Resident of Islamabad</p><p className="self-end font-bold">Petitioner</p><p><strong>Versus</strong></p><span/><p><strong>Federation of Pakistan</strong><br/>Through Secretary, Islamabad</p><p className="self-end font-bold">Respondent</p></div><h3 className="text-center font-bold underline">CONSTITUTIONAL PETITION UNDER ARTICLE 199</h3><p className="mt-6">Respectfully Sheweth:</p><ol className="mt-4 list-decimal space-y-4 pl-5"><li>That the Petitioner is aggrieved by the administrative order dated 06 January 2026, issued without a meaningful opportunity of hearing. <TrustBadge status="verified" compact/></li><li>That Article 10A of the Constitution of Pakistan guarantees the right to fair trial and due process. <TrustBadge status="verified" compact/></li><li>That the impugned action is without lawful authority and of no legal effect. <TrustBadge status="arguable" compact/></li></ol><h3 className="mt-8 font-bold">PRAYER</h3><p className="mt-3">It is respectfully prayed that this Honourable Court may set aside the impugned order and grant any other relief deemed just and proper.</p></article></main><aside className="border-l bg-card p-4"><div className="flex gap-1 border-b pb-3">{["AI","Sources","Case Data"].map((x,i)=><button className={cn("flex-1 rounded-sm py-2 text-[10px] font-bold",i===2?"bg-secondary text-primary":"text-muted-foreground")} key={x}>{x}</button>)}</div><p className="mt-5 text-[10px] font-bold uppercase text-muted-foreground">Case Data</p><div className="mt-3 space-y-3 text-xs">{[["Case number","2026-CV-0182"],["Court","Islamabad High Court"],["Parties","Ali / Federation"],["Jurisdiction","Article 199"]].map(([a,b])=><div key={a}><p className="text-muted-foreground">{a}</p><p className="font-semibold">{b}</p></div>)}</div><p className="mt-6 text-[10px] font-bold uppercase text-muted-foreground">Legal Sources</p><div className="mt-3 space-y-3">{[["Article 10A","verified"],["PLD 2022 SC 123","verified"],["2021 CLC 884","arguable"]].map(([x,t])=><div className="rounded-sm border p-3" key={x}><p className="text-xs font-semibold">{x}</p><div className="mt-2"><TrustBadge status={t as Trust}/></div></div>)}</div></aside></div></div></div>}

function Linter(){const issues=[{s:"pass",t:"Court identified",d:"Islamabad High Court appears in the title."},{s:"pass",t:"Case number present",d:"Constitutional Petition No. 2026 of 2026."},{s:"pass",t:"Parties identified",d:"Petitioner and respondent are stated."},{s:"pass",t:"Required sections present",d:"Facts, grounds, and prayer detected."},{s:"warn",t:"Required affidavit may be missing",d:"No affidavit was detected after the prayer."},{s:"warn",t:"Formatting issue detected",d:"Paragraph 8 uses inconsistent numbering."},{s:"fail",t:"Required annexure missing",d:"Annexure P-2 is cited but not attached."}];return <><PageIntro title="Procedural Linter" subtitle="Check legal documents against filing and format requirements." actions={<Button variant="outline"><FolderOpen/>Select Document</Button>}/><div className="grid gap-6 xl:grid-cols-[280px_1fr]"><Card className="flex flex-col items-center p-6"><p className="text-xs font-bold text-muted-foreground">COMPLIANCE SCORE</p><div className="relative mt-6 flex size-40 items-center justify-center rounded-full bg-[conic-gradient(var(--success)_0_82%,var(--muted)_82%)]"><div className="flex size-32 flex-col items-center justify-center rounded-full bg-card"><span className="text-4xl font-bold">82%</span><span className="text-[10px] text-muted-foreground">GOOD</span></div></div><p className="mt-5 text-center text-xs leading-5 text-muted-foreground">Constitutional Petition Draft v3<br/>Islamabad High Court</p></Card><div className="space-y-3">{issues.map((x,i)=>{const Icon=x.s==="pass"?CheckCircle2:x.s==="warn"?AlertCircle:X;return <Card className="p-4" key={x.t}><div className="flex flex-col gap-3 sm:flex-row sm:items-center"><Icon className={cn("size-5 shrink-0",x.s==="pass"?"text-success":x.s==="warn"?"text-warning":"text-danger")}/><div className="flex-1"><div className="flex items-center gap-2"><h3 className="text-sm font-semibold">{x.t}</h3><span className="text-[9px] font-bold uppercase text-muted-foreground">{x.s==="pass"?"Passed":x.s==="warn"?"Warning":"Error"}</span></div><p className="mt-1 text-xs text-muted-foreground">{x.d}</p>{x.s!=="pass"&&<p className="mt-2 text-[11px] text-primary"><strong>Suggested fix:</strong> {i===4?"Attach a sworn affidavit in the prescribed form.":i===5?"Renumber paragraphs sequentially.":"Upload and label Annexure P-2."}</p>}</div>{x.s!=="pass"&&<div className="flex gap-1"><Button size="sm">Fix Issue</Button><Button size="sm" variant="ghost">Ignore</Button><Button size="icon" variant="ghost" title="View in document"><FileSearch/></Button></div>}</div></Card>})}</div></div></>}

function Documents(){const [uploading,setUploading]=useState(false);const [stage,setStage]=useState(0);const stages=["Uploading","Parsing","Extracting Facts","Indexing","Ready"];const start=()=>{setUploading(true);setStage(0);const timer=setInterval(()=>setStage(s=>{if(s>=4){clearInterval(timer);setTimeout(()=>setUploading(false),800);return 4}return s+1}),500)};return <><PageIntro title="Documents" subtitle="Securely organize and analyze your case record." actions={<Button onClick={start}><Upload/>Upload Document</Button>}/><button onClick={start} className="mb-6 flex w-full flex-col items-center justify-center rounded-md border-2 border-dashed bg-card py-8 transition hover:border-primary hover:bg-info-soft"><Upload className="size-6 text-primary"/><p className="mt-3 text-sm font-semibold">Drop files here or choose files</p><p className="mt-1 text-xs text-muted-foreground">PDF, DOCX, and images · up to 50 MB</p></button>{uploading&&<Card className="mb-6 p-5"><div className="flex items-center justify-between"><p className="text-xs font-semibold">Processing show-cause-notice.pdf</p><span className="text-xs text-primary">{stages[stage]}</span></div><div className="mt-4 grid grid-cols-5 gap-1">{stages.map((x,i)=><div key={x}><div className={cn("h-1 rounded-full",i<=stage?"bg-primary":"bg-muted")}/><p className="mt-2 hidden text-[9px] text-muted-foreground sm:block">{x}</p></div>)}</div></Card>}<div className="grid gap-6 xl:grid-cols-[1fr_310px]"><div className="overflow-x-auto rounded-md border bg-card"><table className="w-full min-w-[700px] text-left text-xs"><thead className="bg-muted"><tr>{["Document","Case","Type","Pages","Uploaded","Status"].map(x=><th className="px-4 py-3 text-[10px] uppercase text-muted-foreground" key={x}>{x}</th>)}</tr></thead><tbody>{[["Impugned Order.pdf","Ali vs. Federation","Order","12","Today","Ready"],["Show Cause Notice.pdf","Ali vs. Federation","Notice","4","Yesterday","Ready"],["Police Report.pdf","Ahmed v. State","Evidence","28","2 days ago","Indexed"],["Property Deed.docx","ABC Property Dispute","Instrument","9","5 days ago","Ready"]].map((r,i)=><tr className="border-t hover:bg-muted/50" key={r[0]}><td className="px-4 py-4 font-semibold"><FileText className="mr-2 inline size-4 text-primary"/>{r[0]}</td>{r.slice(1).map((x,j)=><td className="px-4" key={j}>{j===4?<span className="text-success">{x}</span>:x}</td>)}</tr>)}</tbody></table></div><Card className="p-5"><SectionHead title="Extracted Details"/><div className="aspect-[4/3] rounded-sm bg-muted p-5"><div className="h-full border bg-card p-4 text-center text-[9px] leading-4 text-muted-foreground"><strong>GOVERNMENT OF PAKISTAN</strong><br/><br/>ORDER<br/><br/>Administrative Licence Division</div></div>{[["Facts","6"],["People","4"],["Dates","9"],["Legal References","3"],["Claims","2"]].map(([x,n])=><div className="flex justify-between border-b py-3 text-xs" key={x}><span>{x}</span><strong>{n}</strong></div>)}</Card></div></>}

function Claims(){const [filter,setFilter]=useState("All");return <><PageIntro title="Opponent Claims" subtitle="Evaluate each assertion against evidence and current law."/><div className="mb-5 flex flex-wrap gap-2">{["All","Supported","Weakly Supported","Contradicted","Unverified"].map(x=><Button variant={filter===x?"default":"outline"} size="sm" onClick={()=>setFilter(x)} key={x}>{x}</Button>)}</div><div className="space-y-4">{claims.map((c,i)=><Card className="p-5" key={c.title}><div className="flex justify-between gap-3"><div><p className="text-[10px] font-bold text-muted-foreground">OPPONENT CLAIM</p><h2 className="mt-2 font-bold">{c.title}</h2></div><span className={cn("h-fit rounded-sm px-2 py-1 text-[10px] font-bold",i===0?"bg-warning-soft text-warning":i===1?"bg-danger-soft text-danger":"bg-success-soft text-success")}>{["Weakly Supported","Contradicted","Supported"][i]}</span></div><div className="mt-4 grid gap-4 border-t pt-4 md:grid-cols-3"><div><p className="text-[10px] text-muted-foreground">SOURCE DOCUMENT</p><p className="mt-1 text-xs font-semibold">{c.evidence}</p></div><div><p className="text-[10px] text-muted-foreground">LEGAL BASIS</p><p className="mt-1 text-xs font-semibold">{c.basis}</p></div><div><p className="text-[10px] text-muted-foreground">CONFIDENCE</p><p className="mt-1 text-xs font-semibold">{["64%","88%","91%"][i]}</p></div></div><div className="mt-4 grid gap-3 md:grid-cols-2"><p className="rounded-sm bg-muted p-3 text-xs"><strong>CaseGuard Analysis:</strong> {c.analysis}</p><p className="rounded-sm bg-info-soft p-3 text-xs"><strong>Counterargument:</strong> The record should be tested against disclosure, timing, and prejudice requirements.</p></div></Card>)}</div></>}

const metrics=[{run:"Run 01",p:84.2,r:81.5,f:87.8,a:86.1},{run:"Run 02",p:87.8,r:84.9,f:91.2,a:89.4},{run:"Run 03",p:89.6,r:87.1,f:93.6,a:91.5},{run:"Run 04",p:92.4,r:89.7,f:95.2,a:93.1}];
function Evaluation(){return <><PageIntro title="Evaluation Dashboard" subtitle="Measure retrieval quality, answer grounding, and trust performance." actions={<Button><Activity/>Run Evaluation</Button>}/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Context Precision","92.4%","+2.8%"],["Context Recall","89.7%","+2.6%"],["Faithfulness","95.2%","+1.6%"],["Answer Relevance","93.1%","+1.6%"]].map(([a,b,c])=><Card className="p-5" key={a}><p className="text-xs font-semibold text-muted-foreground">{a}</p><p className="mt-3 text-2xl font-bold">{b}</p><p className="mt-2 text-[11px] font-semibold text-success">{c} vs previous run</p></Card>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_340px]"><Card className="p-5"><SectionHead title="Metric Performance Across Runs"/><div className="h-72"><ResponsiveContainer><LineChart data={metrics}><XAxis dataKey="run" tick={{fontSize:11}}/><YAxis domain={[70,100]} tick={{fontSize:11}}/><Tooltip/><Line dataKey="p" name="Precision" stroke="var(--info)" strokeWidth={2}/><Line dataKey="r" name="Recall" stroke="var(--warning)" strokeWidth={2}/><Line dataKey="f" name="Faithfulness" stroke="var(--success)" strokeWidth={2}/><Line dataKey="a" name="Relevance" stroke="var(--primary)" strokeWidth={2}/></LineChart></ResponsiveContainer></div></Card><Card className="p-5"><SectionHead title="Trust Performance"/>{[["Citation verification rate","96.8%"],["Hallucinated citation rate","1.2%"],["Sources verified","1,284"],["Sources requiring review","18"]].map(([a,b],i)=><div className="flex items-center justify-between border-b py-4" key={a}><span className="text-xs text-muted-foreground">{a}</span><strong className={cn("text-sm",i===1?"text-success":i===3?"text-warning":"")}>{b}</strong></div>)}</Card></div><Card className="mt-6 overflow-hidden"><table className="w-full text-left text-xs"><thead className="bg-muted"><tr>{["Run","Date","Precision","Recall","Faithfulness","Relevance"].map(x=><th className="px-4 py-3 text-[10px] uppercase text-muted-foreground" key={x}>{x}</th>)}</tr></thead><tbody>{metrics.map((m,i)=><tr className="border-t" key={m.run}><td className="px-4 py-4 font-semibold">{m.run}</td><td className="px-4">{["02 Sep 2026","05 Sep 2026","09 Sep 2026","13 Sep 2026"][i]}</td><td className="px-4">{m.p}%</td><td className="px-4">{m.r}%</td><td className="px-4">{m.f}%</td><td className="px-4">{m.a}%</td></tr>)}</tbody></table></Card></>}

function SettingsPage(){const [tab,setTab]=useState("Profile");return <><PageIntro title="Settings" subtitle="Manage your account, security, and verification preferences."/><div className="grid gap-6 lg:grid-cols-[220px_1fr]"><nav className="space-y-1">{["Profile","Security","Notifications","Data & Privacy","Legal Sources","Verification Settings"].map(x=><button key={x} onClick={()=>setTab(x)} className={cn("w-full rounded-sm px-3 py-2 text-left text-xs font-semibold",tab===x?"bg-secondary text-primary":"text-muted-foreground hover:bg-muted")}>{x}</button>)}</nav><Card className="p-6"><h2 className="text-lg font-bold">{tab}</h2><p className="mt-1 text-sm text-muted-foreground">Configure your {tab.toLowerCase()} preferences.</p>{tab==="Security"?<div className="mt-6 space-y-4"><div className="flex gap-3 rounded-sm border border-success/20 bg-success-soft p-4 text-success"><ShieldCheck className="size-5 shrink-0"/><div><p className="text-sm font-bold">Protected by design</p><p className="mt-1 text-xs">Case data is encrypted at rest and in transit.</p><p className="mt-1 text-xs">No case data is used to train external models.</p></div></div><Button>Change Password</Button></div>:<div className="mt-6 max-w-lg space-y-4"><label className="block text-xs font-semibold">Full name<Input className="mt-2" defaultValue="Ayesha Khan"/></label><label className="block text-xs font-semibold">Email<Input className="mt-2" defaultValue="ayesha@chambers.pk"/></label><label className="flex items-center justify-between rounded-sm border p-4 text-sm">Require fresh verification for generated drafts<input type="checkbox" defaultChecked className="accent-primary"/></label><Button>Save Changes</Button></div>}</Card></div></>}

function Notifications({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){const notes=[["Citation requires verification","Ali vs. Federation","High"],["Source has not been reverified recently","ABC Property Dispute","Medium"],["New judgment added","Supreme Court of Pakistan","Info"],["Procedural issue detected","Petition Draft v3","High"],["Document processing completed","Show Cause Notice.pdf","Info"],["Strategy analysis completed","Ahmed v. State","Info"]];return <Sheet open={open} onOpenChange={onOpenChange}><SheetContent className="w-full p-0 sm:max-w-md"><SheetHeader className="border-b p-5"><SheetTitle>Notifications</SheetTitle><SheetDescription>Updates requiring your attention.</SheetDescription></SheetHeader><div className="divide-y">{notes.map(([a,b,s],i)=><div className="flex gap-3 p-4" key={a}><span className={cn("mt-1 size-2 shrink-0 rounded-full",s==="High"?"bg-danger":s==="Medium"?"bg-warning":"bg-info")}/><div className="flex-1"><p className="text-xs font-semibold">{a}</p><p className="mt-1 text-[11px] text-muted-foreground">{b}</p></div><time className="text-[10px] text-muted-foreground">{i+1}h</time></div>)}</div></SheetContent></Sheet>}

export function CaseGuardApp({page}:{page:PageKey}){const [collapsed,setCollapsed]=useState(false);const [mobile,setMobile]=useState(false);const [notifications,setNotifications]=useState(false);const content:Record<PageKey,ReactNode>={dashboard:<Dashboard/>,cases:<CasesPage/>,case:<CasePage/>,research:<Research/>,precedents:<Precedents/>,strategy:<Strategy/>,"stress-test":<StressTest/>,drafting:<Drafting/>,linter:<Linter/>,documents:<Documents/>,claims:<Claims/>,evaluation:<Evaluation/>,settings:<SettingsPage/>};return <div className="min-h-screen bg-background"><Sidebar collapsed={collapsed} onToggle={()=>setCollapsed(v=>!v)} mobileOpen={mobile} onMobileClose={()=>setMobile(false)}/><div className={cn("transition-all",collapsed?"lg:pl-16":"lg:pl-64")}><Header title={titleMap[page]} onMenu={()=>setMobile(true)} onNotifications={()=>setNotifications(true)}/><main className="cg-rise p-4 sm:p-6 lg:p-8">{content[page]}</main></div><Notifications open={notifications} onOpenChange={setNotifications}/><p className="fixed bottom-2 right-3 z-20 text-[9px] text-muted-foreground">Prototype demo · Not legal advice</p></div>}

export function AuthPage({mode}:{mode:"login"|"signup"|"forgot"}){const [sent,setSent]=useState(false);return <div className="grid min-h-screen bg-card lg:grid-cols-[1.05fr_.95fr]"><section className="hidden bg-navy p-12 text-primary-foreground lg:flex lg:flex-col"><div className="flex items-center gap-3"><span className="flex size-10 items-center justify-center rounded-md bg-primary-foreground text-navy"><Scale/></span><span className="text-lg font-bold">CaseGuard AI</span></div><div className="my-auto max-w-xl"><span className="text-xs font-bold uppercase text-primary-foreground/50">Research. Verify. Strategize. Defend.</span><h1 className="mt-5 text-5xl font-bold leading-[1.1]">Legal intelligence<br/>you can verify.</h1><p className="mt-6 max-w-lg text-base leading-7 text-primary-foreground/70">Research, analyze, strategize and draft with evidence-backed legal intelligence for Pakistan.</p><div className="mt-10 flex gap-6 text-xs text-primary-foreground/65"><span className="flex items-center gap-2"><ShieldCheck className="size-4 text-success"/>Source verified</span><span className="flex items-center gap-2"><FileCheck2 className="size-4 text-success"/>Procedurally checked</span></div></div><p className="text-xs text-primary-foreground/35">An all-in-one, verifiable legal workspace for Pakistan.</p></section><section className="flex items-center justify-center p-6"><div className="w-full max-w-sm"><div className="mb-8 flex items-center gap-3 lg:hidden"><span className="flex size-9 items-center justify-center rounded-md bg-navy text-primary-foreground"><Scale/></span><span className="font-bold">CaseGuard AI</span></div><h2 className="text-2xl font-bold">{mode==="login"?"Welcome back":mode==="signup"?"Create your account":"Reset your password"}</h2><p className="mt-2 text-sm text-muted-foreground">{mode==="forgot"?"We’ll send a secure reset link to your email.":"Access your trusted legal workspace."}</p>{sent?<div className="mt-8 rounded-sm border border-success/20 bg-success-soft p-5 text-success"><CheckCircle2/><p className="mt-3 text-sm font-bold">Check your inbox</p><p className="mt-1 text-xs">A password reset link has been sent.</p></div>:<form className="mt-8 space-y-4" onSubmit={e=>{e.preventDefault();if(mode==="forgot")setSent(true)}}>{mode==="signup"&&<label className="block text-xs font-semibold">Full name<Input className="mt-2 h-11" placeholder="Your full name"/></label>}<label className="block text-xs font-semibold">Email<Input type="email" className="mt-2 h-11" placeholder="name@chambers.pk" required/></label>{mode!=="forgot"&&<label className="block text-xs font-semibold">Password<Input type="password" className="mt-2 h-11" placeholder="Enter your password" required/></label>}{mode==="login"&&<div className="flex items-center justify-between text-xs"><label className="flex items-center gap-2"><input type="checkbox" className="accent-primary"/>Remember me</label><Link to="/forgot-password" className="font-semibold text-primary">Forgot password?</Link></div>}<Button type="submit" className="h-11 w-full" asChild={mode==="login"}><Link to={mode==="login"?"/":"/login"}>{mode==="login"?"Sign In":mode==="signup"?"Create Account":"Send Reset Link"}</Link></Button></form>}<p className="mt-6 text-center text-xs text-muted-foreground">{mode==="login"?"New to CaseGuard? ":"Already have an account? "}<Link to={mode==="login"?"/signup":"/login"} className="font-semibold text-primary">{mode==="login"?"Sign Up":"Sign In"}</Link></p><p className="mt-10 text-center text-[10px] text-muted-foreground">Prototype demo. Outputs must be independently reviewed and are not legal advice.</p></div></section></div>}